{"code": "import pytest
import impl

# Core formatting with different exponents
def test_basic_usd_formatting():
    """Basic USD formatting with 2 decimal places"""
    exponents = {"USD": 2}
    assert impl.format_amount("123.45", "USD", exponents) == "123.45"

def test_different_exponent_currencies():
    """Test JPY (0), KWD (3), CLF (4) with different exponents"""
    exponents = {"JPY": 0, "KWD": 3, "CLF": 4}
    assert impl.format_amount("1234.5", "JPY", exponents) == "1234"
    assert impl.format_amount("1.234", "KWD", exponents) == "1.234"
    assert impl.format_amount("1.2345", "CLF", exponents) == "1.2345"

def test_negative_amounts():
    """Negative amounts preserve their sign"""
    exponents = {"USD": 2}
    assert impl.format_amount("-123.45", "USD", exponents) == "-123.45"
    assert impl.format_amount("-999.99", "USD", exponents) == "-999.99"

# ROUND_HALF_EVEN rounding behavior
def test_round_half_even_rounding():
    """ROUND_HALF_EVEN: 2.675->2.68 (to even), 2.665->2.66 (to even)"""
    exponents = {"USD": 2}
    assert impl.format_amount("2.675", "USD", exponents) == "2.68"
    assert impl.format_amount("2.665", "USD", exponents) == "2.66"

def test_negative_rounding_half_even():
    """Negative values round symmetrically with ROUND_HALF_EVEN"""
    exponents = {"USD": 2}
    assert impl.format_amount("-2.675", "USD", exponents) == "-2.68"
    assert impl.format_amount("-2.665", "USD", exponents) == "-2.66"

# Zero handling
def test_zero_from_positive_becomes_unsigned():
    """Zero from positive values is formatted as unsigned"""
    exponents = {"USD": 2}
    assert impl.format_amount("0.001", "USD", exponents) == "0.00"
    assert impl.format_amount("0.004", "USD", exponents) == "0.00"

def test_zero_from_negative_becomes_unsigned():
    """Zero from negative values is formatted as unsigned"""
    exponents = {"USD": 2, "JPY": 0}
    assert impl.format_amount("-0.004", "USD", exponents) == "0.00"
    assert impl.format_amount("-0.4", "JPY", exponents) == "0"

def test_explicit_zero():
    """Explicit zero formatting with different exponents"""
    exponents = {"USD": 2, "JPY": 0, "KWD": 3}
    assert impl.format_amount("0", "USD", exponents) == "0.00"
    assert impl.format_amount("0", "JPY", exponents) == "0"
    assert impl.format_amount("0", "KWD", exponents) == "0.000"

# Decimal padding and decimal point rules
def test_zero_padding_fewer_decimals_than_exponent():
    """Decimal places are zero-padded to match exponent"""
    exponents = {"USD": 2, "KWD": 3}
    assert impl.format_amount("123", "USD", exponents) == "123.00"
    assert impl.format_amount("1.2", "KWD", exponents) == "1.200"

def test_no_decimal_point_when_exponent_zero():
    """Exponent 0 produces no decimal point"""
    exponents = {"JPY": 0}
    assert impl.format_amount("1234.999", "JPY", exponents) == "1235"
    # Should never be "1234." or "1234.0"
    assert "." not in impl.format_amount("1234", "JPY", exponents)

# Input format variations
def test_scientific_notation():
    """Scientific notation is parsed correctly"""
    exponents = {"USD": 2}
    assert impl.format_amount("1E+2", "USD", exponents) == "100.00"
    assert impl.format_amount("1.5e-3", "USD", exponents) == "0.00"

def test_whitespace_and_explicit_sign():
    """Whitespace and explicit plus sign are handled"""
    exponents = {"USD": 2}
    assert impl.format_amount("  123.45  ", "USD", exponents) == "123.45"
    assert impl.format_amount("+123.45", "USD", exponents) == "123.45"

# Error cases: KeyError for unknown currency
def test_unknown_currency_raises_keyerror():
    """Unknown currency code raises KeyError"""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("100.00", "EUR", exponents)

def test_currency_lookup_before_amount_validation():
    """Currency is looked up BEFORE amount is parsed (KeyError takes precedence)"""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("invalid", "XXX", exponents)

# Error cases: ValueError for invalid amounts
def test_invalid_amount_formats_raise_valueerror():
    """Invalid amount formats raise ValueError"""
    exponents = {"USD": 2}
    invalid_amounts = [
        "",           # empty
        "abc",        # non-numeric
        "1.2.3",      # malformed decimal
        "12,34",      # comma decimal separator
        "$1.00",      # currency symbol
        "1 000.00",   # thousands separator
    ]
    for invalid in invalid_amounts:
        with pytest.raises(ValueError):
            impl.format_amount(invalid, "USD", exponents)

def test_non_finite_values_raise_valueerror():
    """Non-finite values (NaN, Infinity) raise ValueError"""
    exponents = {"USD": 2}
    non_finite = ["NaN", "sNaN", "Infinity", "-Infinity"]
    for value in non_finite:
        with pytest.raises(ValueError):
            impl.format_amount(value, "USD", exponents)
